select * from in_record


        AND in_time BETWEEN #{start} AND #{end}


        AND bill_no LIKE CONCAT('%', #{billNo}, '%')


        AND (
            bill_no LIKE CONCAT('%', #{keyword}, '%')
            OR batch_no LIKE CONCAT('%', #{keyword}, '%')
        )


        AND in_user = #{inUser}


ORDER BY in_time DESC

